const app=document.querySelector('#app'); let selectedProvince='Nampula';
function go(route){location.hash='#/'+route;document.querySelector('.sidebar')?.classList.remove('open')}
function header(title,sub,action=''){return `<div class="page-head"><div class="page-title"><span class="eyebrow">PG13 · Centro de Gestão</span><h1>${title}</h1><p>${sub}</p></div><div class="actions"><span class="demo-pill">Dados demonstrativos</span>${action}</div></div>`}
function detailHeader(backRoute,backLabel,title,sub,action=''){return `<div class="page-head"><div class="page-title"><button class="back-btn" onclick="go('${backRoute}')">← Voltar para ${backLabel}</button><div class="breadcrumb"><a href="#/dashboard">PG13</a><span>›</span><a href="#/${backRoute}">${backLabel}</a><span>›</span><strong>${title}</strong></div><div class="page-context"><h1>${title}</h1><p>${sub}</p></div></div><div class="actions"><span class="demo-pill">Dados demonstrativos</span>${action}</div></div>`}
function shell(content,active){return `<div class="shell"><aside class="sidebar"><div class="side-brand"><div class="mark">PG13</div><div class="brand-copy"><div class="brand-title">PG13</div><div class="brand-sub">Plataforma de Gestão do 13.º Congresso da FRELIMO</div></div></div><div class="side-label">Comando Nacional</div><nav class="nav">${nav.map(n=>`<a href="#/${n[0]}" class="${active===n[0]?'active':''}">${svg(n[2])}<span>${n[1]}</span></a>`).join('')}</nav><div class="side-foot"><div class="security-card"><strong>Ambiente protegido</strong>Protótipo demonstrativo. Controlos avançados representam capacidades previstas.</div></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-toggle" onclick="document.querySelector('.sidebar').classList.toggle('open')">☰</button><div class="search"><input aria-label="Pesquisa global" placeholder="Pesquisar pessoa, documento, tarefa ou estrutura…"></div><div class="top-actions"><button class="icon-btn" onclick="showNotifications()" aria-label="Notificações">${svg('file')}<i class="dot"></i></button><div class="access"><span>Nível de acesso</span><strong>NÍVEL 2 · CONFIDENCIAL</strong></div><div class="avatar">AM</div></div></header><div class="content">${content}</div></main></div>`}
function login(){app.innerHTML=`<section class="login"><div class="login-main"><div class="login-brand"><img class="login-brand-emblem" src="assets/brand/pg13-emblem.png" alt="Emblema PG13"><div><div class="brand-title">PG13</div><div class="brand-sub">Plataforma de Gestão do 13.º Congresso da FRELIMO</div></div></div><span class="eyebrow">Ambiente Institucional Protegido</span><h1>Acesso à plataforma</h1><p class="login-lead">Gestão integrada da preparação, organização e execução do 13.º Congresso.</p><form onsubmit="event.preventDefault();go('dashboard')"><div class="field"><label>Utilizador / Email</label><input value="gestor.nacional@pg13.demo" aria-label="Utilizador ou email"></div><div class="field"><label>Palavra-passe</label><input type="password" value="demonstracao" aria-label="Palavra-passe"></div><button class="primary" style="width:100%;margin-top:10px">ENTRAR NA PG13</button></form><div class="login-notice">${svg('shield')}<div><strong>Acesso reservado a utilizadores autorizados.</strong><br>Esta versão utiliza dados exclusivamente demonstrativos.</div></div></div><aside class="login-art"><img class="login-emblem" src="assets/brand/pg13-emblem.png" alt="Emblema PG13 — 13.º Congresso da FRELIMO"><div class="art-copy"><span class="art-label">Julho 2027 · Nampula</span><h2>Gestão.<br>Comando.<br>Rastreabilidade.</h2><p>Uma visão nacional do estado de preparação, da estrutura à execução — com responsabilidade em cada nível.</p></div></aside></section>`}
function metric(label,num,trend,bad=false){return `<div class="metric"><div class="metric-top"><span class="metric-label">${label}</span><span style="color:var(--red)">●</span></div><div class="num">${num}</div><span class="trend ${bad?'warn':''}">${trend}</span></div>`}
function dashboard(){const content=header('Centro Nacional de Gestão e Acompanhamento','Visão consolidada do processo de preparação do 13.º Congresso.')+`<section class="hero"><div><span class="eyebrow" style="color:#ffd7dc">13.º Congresso · Nampula</span><h2>20–25 Julho 2027</h2><p>Estado nacional da preparação e execução das estruturas.</p></div><div class="hero-date"><div class="count"><strong id="days">301</strong><span>Dias restantes</span></div><div class="count"><strong>83%</strong><span>Preparação global</span></div></div></section><div class="metrics">${metric('Províncias activas','11/11','Cobertura nacional')}${metric('Distritos reportados','157','92% reportaram')}${metric('Delegados registados','2.480','+64 esta semana')}${metric('Candidaturas em análise','18','7 aguardam decisão',true)}${metric('Pendências críticas','24','Requer atenção',true)}</div><div class="grid grid-2"><section class="card"><div class="card-head"><h3>Preparação por área funcional</h3><a class="link" href="#/logistica">Ver detalhe →</a></div><div class="card-body progress-list">${[['Actividade Interna e Formação',86],['Mobilização, Comunicação e Imagem',78],['Finanças e Logística',74],['Documentação',89],['Relações Exteriores e Protocolo',68],['Verificação de Candidaturas',81]].map(x=>`<div class="progress-row"><span>${x[0]}</span><div class="progress"><i style="width:${x[1]}%"></i></div><strong>${x[1]}%</strong></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Liderança institucional</h3><a class="link" href="#/lideranca">Liderança →</a></div><div class="card-body institutional"><div class="portrait"></div><div><h3>Daniel Francisco Chapo</h3><p>Presidente da República de Moçambique</p><div class="quote">Espaço reservado para mensagem institucional oficial.</div></div></div></section><section class="card"><div class="card-head"><h3>Estrutura nacional</h3><a href="#/estrutura" class="link">Explorar mapa →</a></div><div class="card-body"><div class="province-grid">${provinces.slice(0,8).map(p=>`<a href="#/provincia/${slug(p.name)}" class="province-card"><span class="pct">${p.prep}%</span><strong>${p.name}</strong><span>${p.districts} distritos · ${p.delegates} delegados</span></a>`).join('')}</div></div></section><section class="card"><div class="card-head"><h3>Tarefas críticas</h3><a href="#/auditoria" class="link">Responsabilização →</a></div><div class="card-body">${[['Validar alojamento da delegação Norte','Logística · prazo hoje','URGENTE'],['Rever relatório de 3 distritos','Gabinete Provincial · 24 Set','ALTA'],['Aprovar orientação PG13-DOC-00481','Documentação · 25 Set','ALTA'],['Confirmar equipa de protocolo','Gabinete Central · 27 Set','NORMAL']].map((x,i)=>`<div class="task"><div><strong>${x[0]}</strong><p>${x[1]}</p></div><span class="status ${i===0?'bad':i<3?'warn':'neutral'}">${x[2]}</span></div>`).join('')}</div></section></div>`;app.innerHTML=shell(content,'dashboard');updateDays()}
function slug(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,'-')}
function coverageDetail(place){const online=place.status==='online';return `<div class="coverage-detail-head"><div><span class="coverage-status ${online?'online':'attention'}"><i></i>${online?'Centro online':'Requer atenção'}</span><h2>${place.name}</h2><p>${place.type}</p></div><span class="coverage-signal">${online?'ONLINE':'ALERTA'}</span></div><div class="coverage-location"><div><span>Distrito</span><strong>${place.district}</strong></div><div><span>Província</span><strong>${place.province}</strong></div><div><span>Latitude</span><strong>${place.lat.toFixed(3)}°</strong></div><div><span>Longitude</span><strong>${place.lon.toFixed(3)}°</strong></div></div><div class="coverage-report"><span>Último reporte</span><strong>${online?'Há menos de 5 minutos':'Aguardando sincronização'}</strong></div>`}
function selectCoveragePlace(id){const data=window.MOZ_MAP_DATA,place=data?.places.find(p=>p.id===Number(id));if(!place)return;document.querySelectorAll('.coverage-point').forEach(p=>p.classList.toggle('selected',p.dataset.id===String(id)));const detail=document.querySelector('#coverage-detail');if(detail)detail.innerHTML=coverageDetail(place);const search=document.querySelector('#coverage-search');if(search)search.value=place.name}
function searchCoverage(value){const data=window.MOZ_MAP_DATA;if(!data||!value)return;const q=value.trim().toLowerCase();const place=data.places.find(p=>p.name.toLowerCase()===q)||data.places.find(p=>p.name.toLowerCase().includes(q)||p.district.toLowerCase().includes(q));if(place)selectCoveragePlace(place.id)}
function detailedNationalMap(data){const selected=data.places.find(p=>p.name==='Maputo')||data.places[0];const alerts=data.places.filter(p=>p.status==='attention').slice(0,8);return `<section class="geo-command"><header class="geo-command-head"><div><span class="geo-live"><i></i>Rede territorial nacional</span><h2>Representatividade em Moçambique</h2><p>Limites distritais e centros de presença organizacional georreferenciados.</p></div><div class="geo-stats"><div><strong>${data.districts.length}</strong><span>Distritos mapeados</span></div><div><strong>${data.places.length}</strong><span>Centros e localidades</span></div><div><strong>90%</strong><span>Centros online</span></div></div></header><div class="geo-command-body"><div class="geo-map-card"><div class="geo-map-toolbar"><div><span><i class="legend-dot online"></i>180 online</span><span><i class="legend-dot attention"></i>20 em atenção</span><span><i class="legend-line"></i>Limite distrital</span></div><strong>Selecione um ponto para ver o detalhe</strong></div><svg class="geo-map" viewBox="0 0 700 1050" role="img" aria-label="Mapa detalhado de Moçambique com 162 distritos e 200 centros de representatividade"><g class="district-layer">${data.districts.map((d,i)=>`<path class="district-shape" data-district="${i}" d="${d.path}"><title>${d.name} · ${d.province}</title></path>`).join('')}</g><g class="coverage-layer">${data.places.map((p,i)=>`<g class="coverage-point ${p.status} ${p.id===selected.id?'selected':''}" data-id="${p.id}" transform="translate(${p.x} ${p.y})" style="--pulse-delay:${(i%17*.11).toFixed(2)}s" onclick="selectCoveragePlace(${p.id})" tabindex="0" role="button" aria-label="${p.name}, ${p.district}, ${p.province}"><circle class="point-pulse" r="6"></circle><circle class="point-core" r="2.7"></circle><title>${p.name} · ${p.district} · ${p.province}</title></g>`).join('')}</g><g class="major-labels">${data.places.filter(p=>p.major).map(p=>`<text x="${p.x+7}" y="${p.y+3}">${p.name}</text>`).join('')}</g></svg><div class="geo-map-caption"><span>Dados administrativos: MozGIS / INE</span><span>Localidades: GeoNames · coordenadas WGS84</span></div></div><aside class="geo-side"><div class="coverage-search"><label for="coverage-search">Localizar centro, distrito ou localidade</label><input id="coverage-search" list="coverage-options" placeholder="Ex.: Nampula, Beira, Mocuba…" oninput="searchCoverage(this.value)"><datalist id="coverage-options">${data.places.map(p=>`<option value="${p.name}">${p.district} · ${p.province}</option>`).join('')}</datalist></div><div id="coverage-detail">${coverageDetail(selected)}</div><section class="attention-list"><div class="attention-title"><span>Centros que requerem atenção</span><strong>${data.places.filter(p=>p.status==='attention').length}</strong></div>${alerts.map(p=>`<button onclick="selectCoveragePlace(${p.id})"><i></i><span><strong>${p.name}</strong><small>${p.district} · ${p.province}</small></span><b>Ver</b></button>`).join('')}</section></aside></div><footer class="geo-foot"><span><i></i> Monitorização demonstrativa · actualização automática</span><span>Os pontos representam centros de cobertura sobre localidades reais.</span></footer></section>`}
function mapa(){const data=window.MOZ_MAP_DATA;if(!data){app.innerHTML=shell(header('Mapa Nacional de Representatividade','A carregar dados cartográficos…')+'<section class="card"><div class="card-body">Não foi possível carregar a camada cartográfica.</div></section>','mapa');return}const content=header('Mapa Nacional de Representatividade','Distritos, centros urbanos e localidades com cobertura operacional em todo o território.',`<button class="secondary" onclick="toast('Camada nacional actualizada agora')">Actualizar mapa</button>`)+detailedNationalMap(data);app.innerHTML=shell(content,'mapa')}
function structure(){const content=header('Estrutura Nacional','Navegue do Gabinete Central até às equipas distritais.')+`<section class="card hierarchy"><div class="hier-node"><strong>Gabinete Central</strong><span>Comando e consolidação nacional</span></div><b class="arrow">→</b><div class="hier-node"><strong>11 Gabinetes Provinciais</strong><span>Coordenação territorial</span></div><b class="arrow">→</b><div class="hier-node"><strong>157 Gabinetes Distritais</strong><span>Execução e reporte</span></div><b class="arrow">→</b><div class="hier-node"><strong>Equipas / Responsáveis</strong><span>Tarefa e responsabilização</span></div></section><div class="map-layout" style="margin-top:16px"><section class="card moz-map"><div class="card-head"><h3>Mapa operacional de Moçambique</h3><span class="subtle">Clique numa província</span></div><svg class="map-svg" viewBox="0 0 520 650" role="img" aria-label="Representação demonstrativa das províncias de Moçambique">${provinces.map((p,i)=>{const y=26+i*52;const x=160+Math.sin(i*.7)*45;const w=190-(i>7?(i-7)*15:0);return `<rect class="province-shape ${p.name===selectedProvince?'active':''}" data-name="${p.name}" x="${x}" y="${y}" width="${w}" height="44" rx="16" onclick="selectProvince('${p.name}')"/><text class="map-label" x="${x+14}" y="${y+27}">${p.name}</text>`}).join('')}</svg></section><aside id="province-panel" class="card">${provincePanel(provinces.find(p=>p.name===selectedProvince))}</aside></div>`;app.innerHTML=shell(content,'estrutura')}
function provincePanel(p){return `<div class="detail-panel"><span class="eyebrow">Gabinete Provincial</span><h2>${p.name}</h2><span class="status good">Operacional</span><div class="big">${p.prep}%</div><span class="subtle">Nível de preparação</span><div class="progress" style="margin-top:9px"><i style="width:${p.prep}%"></i></div><div class="detail-list"><div class="detail-item"><span>Distritos reportados</span><strong>${p.districts}</strong></div><div class="detail-item"><span>Delegados</span><strong>${p.delegates}</strong></div><div class="detail-item"><span>Documentos pendentes</span><strong>${p.docs}</strong></div><div class="detail-item"><span>Tarefas críticas</span><strong>${p.tasks}</strong></div></div><button class="primary" style="width:100%" onclick="go('provincia/${slug(p.name)}')">ABRIR PROVÍNCIA</button></div>`}
function selectProvince(name){selectedProvince=name;document.querySelectorAll('.province-shape').forEach(x=>x.classList.toggle('active',x.dataset.name===name));document.querySelector('#province-panel').innerHTML=provincePanel(provinces.find(p=>p.name===name))}
function provincePage(s){const p=provinces.find(x=>slug(x.name)===s)||provinces[2];const districts=['Nampula Cidade','Angoche','Mecubúri','Memba','Mogincual','Monapo','Mossuril','Muecate'];const content=header(p.name,`Gabinete Provincial · ${p.districts} distritos reportados · acompanhamento territorial`,`<button class="secondary" onclick="go('delegados?provincia=${slug(p.name)}')">Ver delegados</button>`)+`<div class="metrics">${metric('Preparação',p.prep+'%','Acima da média')}${metric('Delegados',p.delegates,'Registados')}${metric('Documentos pendentes',p.docs,'Em tratamento',p.docs>5)}${metric('Tarefas críticas',p.tasks,'Responsáveis notificados',p.tasks>2)}${metric('Aprovações','7','Em curso')}</div><section class="card"><div class="card-head"><h3>Distritos e execução</h3><span class="subtle">Actualizado há 24 min</span></div><div class="card-body province-grid">${districts.map((d,i)=>`<a class="province-card" href="#/distrito/${slug(d)}"><span class="pct">${72+i*3}%</span><strong>${d}</strong><span>${14+i*2} delegados · ${i%3} pendências</span></a>`).join('')}</div></section>`;app.innerHTML=shell(content,'estrutura')}
function districtPage(s){const name=s.split('-').map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ');const content=header(name,'Gabinete Distrital · execução local e reporte à estrutura provincial')+`<div class="metrics">${metric('Preparação','84%','Em execução')}${metric('Delegados','28','26 confirmados')}${metric('Documentos','14','2 pendentes')}${metric('Tarefas','9','1 atrasada',true)}${metric('Último reporte','Hoje','09:45')}</div><div class="grid grid-2"><section class="card"><div class="card-head"><h3>Plano distrital</h3></div><div class="card-body progress-list">${[['Mobilização local',91],['Documentação de delegados',86],['Transporte para Nampula',72],['Comunicação e orientações',88]].map(x=>`<div class="progress-row"><span>${x[0]}</span><div class="progress"><i style="width:${x[1]}%"></i></div><strong>${x[1]}%</strong></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Responsável</h3></div><div class="card-body institutional"><div class="portrait"></div><div><h3>Responsável Demonstrativo</h3><p>Coordenador Distrital</p><div class="quote">Último reporte submetido hoje às 09:45.</div></div></div></section></div>`;app.innerHTML=shell(content,'estrutura')}
function delegateTable(){return `<div class="table-wrap"><table class="table"><thead><tr><th>Delegado</th><th>Código</th><th>Província</th><th>Distrito</th><th>Função</th><th>Estado</th></tr></thead><tbody>${delegates.map((d,i)=>`<tr class="clickable" onclick="go('delegado/${d[0].toLowerCase()}')"><td><div class="person"><div class="mini-avatar">${d[1].split(' ').map(x=>x[0]).join('').slice(0,2)}</div><strong>${d[1]}</strong></div></td><td class="code">${d[0]}</td><td>${d[2]}</td><td>${d[3]}</td><td>${d[4]}</td><td><span class="status ${d[5]==='Pendente'||d[5]==='Documentação'?'warn':'good'}">${d[5]}</span></td></tr>`).join('')}</tbody></table></div>`}
function delegatesPage(){const content=header('Delegados','Registo, confirmação documental e acreditação nacional.',`<button class="primary" onclick="toast('Registo demonstrativo aberto')">Registar delegado</button>`)+`<div class="metrics">${metric('Total nacional','2.480','11 províncias')}${metric('Confirmados','2.291','92,4%')}${metric('Acreditados','1.864','75,2%')}${metric('Documentação pendente','124','Requer validação',true)}${metric('Em verificação','65','Equipa responsável')}</div><section class="card"><div class="card-head"><h3>Directório nacional</h3><span class="subtle">Clique para abrir o perfil completo</span></div><div class="card-body"><div class="filter-row"><input id="delegate-search" placeholder="Pesquisar nome ou código…" oninput="filterRows(this.value)"><select><option>Todas as províncias</option>${provinces.map(p=>`<option>${p.name}</option>`)}</select><select><option>Todos os distritos</option><option>Nampula Cidade</option><option>Angoche</option></select><select><option>Todos os estados</option><option>Confirmado</option><option>Acreditado</option><option>Pendente</option></select></div>${delegateTable()}</div></section>`;app.innerHTML=shell(content,'delegados')}
function delegatePage(id){const d=delegates.find(x=>x[0].toLowerCase()===id)||delegates[1];const content=header(d[1],`${d[0]} · Perfil institucional do delegado`)+`<div class="grid grid-2"><section class="card"><div class="card-body"><div class="institutional"><div class="portrait" style="width:120px;height:145px"></div><div><span class="status good">${d[5]}</span><h2 style="margin:12px 0 4px">${d[1]}</h2><p>${d[4]} · ${d[2]}</p><p class="code">${d[0]}</p></div></div><div class="meta-grid"><div class="meta"><span>Província</span><strong>${d[2]}</strong></div><div class="meta"><span>Distrito</span><strong>${d[3]}</strong></div><div class="meta"><span>Contacto</span><strong>+258 8X XXX XXXX</strong></div><div class="meta"><span>Acreditação</span><strong>${d[5]}</strong></div></div></div></section><section class="card"><div class="card-head"><h3>Documentação</h3></div><div class="card-body"><div class="detail-list"><div class="detail-item"><span>Ficha de inscrição</span><span class="status good">Validada</span></div><div class="detail-item"><span>Identificação</span><span class="status good">Validada</span></div><div class="detail-item"><span>Credencial</span><span class="status warn">Em produção</span></div><div class="detail-item"><span>Confirmação provincial</span><span class="status good">Concluída</span></div></div></div></section><section class="card"><div class="card-head"><h3>Histórico</h3></div><div class="card-body timeline">${[['18 Set · 14:22','Acreditação confirmada'],['17 Set · 10:05','Documentação validada'],['15 Set · 16:31','Registo submetido pela província']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Observações controladas</h3></div><div class="card-body"><p class="subtle">Sem observações activas. Este campo está disponível apenas para utilizadores autorizados.</p></div></section></div>`;app.innerHTML=shell(content,'delegados')}
function candidaturas(){const content=header('Candidaturas','Verificação, análise e decisão com classificação de sigilo.')+`<div class="metrics">${metric('Total','149','Processos registados')}${metric('Em análise','18','12% do total')}${metric('Aprovadas','106','71% do total')}${metric('Pendentes','17','Requer documentação',true)}${metric('Rejeitadas','8','Decisão registada')}</div><section class="card"><div class="card-head"><h3>Processos</h3><span class="security level l1">NÍVEL 1 = SIGILO MÁXIMO</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Candidato</th><th>Origem</th><th>Processo</th><th>Estado</th><th>Responsável</th><th>Sigilo</th><th>Data</th></tr></thead><tbody>${candidates.map(c=>`<tr class="clickable" onclick="go('candidatura/${c[0].toLowerCase()}')"><td class="code">${c[0]}</td><td><strong>${c[1]}</strong></td><td>${c[2]}</td><td>${c[3]}</td><td><span class="status ${c[4]==='Aprovada'?'good':c[4]==='Rejeitada'?'bad':'warn'}">${c[4]}</span></td><td>${c[5]}</td><td>${level(c[6])}</td><td>${c[7]}</td></tr>`).join('')}</tbody></table></div></section>`;app.innerHTML=shell(content,'candidaturas')}
function level(l){return `<span class="level l${l.match(/\d/)?.[0]||3}">${l.toUpperCase()}</span>`}
function candidaturaPage(id){const c=candidates.find(x=>x[0].toLowerCase()===id)||candidates[0];const content=header(`Candidatura ${c[0]}`,`${c[1]} · Processo demonstrativo controlado`)+`<section class="doc-hero"><span class="eyebrow" style="color:#ffcbd1">Processo de candidatura</span><h1>${c[1]}</h1><p>${c[2]} · ${c[3]}</p><div class="watermark">ACESSO IDENTIFICADO · UTILIZADOR PG13-00451</div></section><div class="meta-grid"><div class="meta"><span>Classificação</span><strong>${c[6]}</strong></div><div class="meta"><span>Estado</span><strong>${c[4]}</strong></div><div class="meta"><span>Responsável</span><strong>${c[5]}</strong></div><div class="meta"><span>Data</span><strong>${c[7]}</strong></div></div><div class="grid grid-equal" style="margin-top:16px"><section class="card"><div class="card-head"><h3>Linha do processo</h3></div><div class="card-body timeline">${[['18 Set · 11:20','Em análise pela equipa nacional'],['17 Set · 16:44','Documentos verificados'],['16 Set · 09:30','Processo recebido da província']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Controlo de acesso</h3></div><div class="card-body"><div class="warning-box">A visualização deste processo é demonstrativa. Em produção, o conteúdo obedecerá às permissões e à classificação atribuída.</div></div></section></div>`;app.innerHTML=shell(content,'candidaturas')}
function documentacao(){const content=header('Documentação','Cofre Documental do Congresso · versões, classificação e acessos.',`<button class="primary" onclick="toast('Novo documento demonstrativo')">Novo documento</button>`)+`<div class="metrics">${metric('Documentos','483','9 categorias')}${metric('Nível 1','38','Acesso restrito')}${metric('Em revisão','27','7 acima do prazo',true)}${metric('Aprovados','391','81% do acervo')}${metric('Versões esta semana','64','Rastreáveis')}</div><section class="card"><div class="card-head"><h3>Acervo documental</h3><span class="subtle">Acessos sujeitos à classificação</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Título</th><th>Área</th><th>Versão</th><th>Classificação</th><th>Estado</th></tr></thead><tbody>${docs.map(d=>`<tr class="clickable" onclick="go('documento/${d[0].toLowerCase()}')"><td class="code">${d[0]}</td><td><strong>${d[1]}</strong></td><td>${d[2]}</td><td>${d[3]}</td><td>${level(d[4])}</td><td><span class="status ${d[5]==='Aprovado'||d[5]==='Publicado'?'good':'warn'}">${d[5]}</span></td></tr>`).join('')}</tbody></table></div></section>`;app.innerHTML=shell(content,'documentacao')}
function documento(id){const d=docs.find(x=>x[0].toLowerCase()===id)||docs[0];const content=header(d[0],d[1],`<button class="secondary" onclick="toast('Acesso registado no histórico demonstrativo')">Registar acesso</button>`)+`<section class="doc-hero"><span class="eyebrow" style="color:#ffcbd1">Documento rastreável · ${d[4]}</span><h1>${d[1]}</h1><p>${d[0]} · ${d[3]} · Departamento de ${d[2]}</p><div class="watermark">CÓPIA IDENTIFICADA — UTILIZADOR PG13-00451</div></section><div class="meta-grid"><div class="meta"><span>Criado por</span><strong>Unidade Documental</strong></div><div class="meta"><span>Revisto por</span><strong>Equipa Nacional</strong></div><div class="meta"><span>Aprovado por</span><strong>Gabinete Central</strong></div><div class="meta"><span>Data e hora</span><strong>18 Set 2026 · 13:45</strong></div><div class="meta"><span>Versão</span><strong>${d[3]}</strong></div><div class="meta"><span>Departamento</span><strong>${d[2]}</strong></div><div class="meta"><span>Autorizados</span><strong>12 utilizadores</strong></div><div class="meta"><span>Estado</span><strong>${d[5]}</strong></div></div><div class="grid grid-equal" style="margin-top:16px"><section class="card"><div class="card-head"><h3>Linha de rastreabilidade</h3></div><div class="card-body timeline">${[['14:02','Acesso concedido ao Grupo Y'],['13:45','Documento aprovado'],['12:14','Versão 3.2 criada'],['11:02','Aberto pelo Utilizador PG13-00451'],['10:31','Submetido para revisão'],['09:12','Documento criado']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Pessoas autorizadas</h3></div><div class="card-body"><div class="detail-list">${['Aprovadores do Gabinete Central','Equipa Documental Nacional','Responsável Provincial autorizado'].map((x,i)=>`<div class="detail-item"><span>${x}</span><span class="level l${i+1}">ACESSO N${i+1}</span></div>`).join('')}</div><div class="warning-box">Watermark e rastreabilidade são capacidades demonstradas visualmente. A implementação de produção requer controlos técnicos próprios.</div></div></section></div>`;app.innerHTML=shell(content,'documentacao')}
function logistica(){const items=[['Alojamento',76,'EM CURSO'],['Transporte',62,'EM CURSO'],['Alimentação',84,'EM CURSO'],['Salas',93,'CONCLUÍDO'],['Equipamentos',71,'ATENÇÃO'],['Material',91,'CONCLUÍDO'],['Credenciação',81,'EM CURSO'],['Delegações',68,'ATRASADO'],['Protocolo',57,'CRÍTICO']];const content=header('Logística','Preparação integrada de recursos, deslocações e operação do Congresso.',`<button class="secondary" onclick="toast('Relatório consolidado preparado')">Exportar resumo</button>`)+`<div class="metrics">${metric('Preparação global','76%','Meta: 85%')}${metric('Frentes concluídas','2/9','Execução activa')}${metric('Itens críticos','1','Protocolo',true)}${metric('Tarefas atrasadas','7','Responsáveis notificados',true)}${metric('Última actualização','09:45','Hoje')}</div><section class="logistics-grid">${items.map((x,i)=>`<article class="log-card"><div class="log-card-head"><div><h3>${x[0]}</h3><p>${3+i} frentes de trabalho</p></div><div class="log-icon">${String(i+1).padStart(2,'0')}</div></div><div class="big-pct">${x[1]}%</div><div class="progress"><i style="width:${x[1]}%"></i></div><div style="margin-top:14px"><span class="status ${x[2]==='CONCLUÍDO'?'good':x[2]==='CRÍTICO'||x[2]==='ATRASADO'?'bad':'warn'}">${x[2]}</span></div></article>`).join('')}</section>`;app.innerHTML=shell(content,'logistica')}
function comunicacao(){const items=[['COMUNICADO','Orientação às estruturas provinciais','Destinatários: Nacional · Províncias','18 Set · 14:30'],['ALERTA','Actualização do calendário de reporte','Destinatários: Distritos','18 Set · 09:15'],['ORIENTAÇÃO','Procedimentos de validação documental','Destinatários: Área de Documentação','17 Set · 16:00'],['CONTEÚDO INTERNO','Resumo semanal de preparação','Destinatários: Gabinete Central','16 Set · 18:40']];const content=header('Comunicação','Comunicados, orientações, alertas e agenda comunicacional.',`<button class="primary" onclick="openComm()">Novo Comunicado</button>`)+`<div class="grid grid-2"><section><div class="comm-grid">${items.map(x=>`<article class="card comm"><span class="eyebrow">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><div class="comm-meta"><span class="subtle">${x[3]}</span><span class="status good">Publicado</span></div></article>`).join('')}</div></section><aside class="card"><div class="card-head"><h3>Agenda comunicacional</h3></div><div class="card-body timeline">${[['22 Set','Nota semanal às províncias'],['24 Set','Orientação às equipas distritais'],['27 Set','Resumo nacional de preparação'],['30 Set','Janela de actualização institucional']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></aside></div>`;app.innerHTML=shell(content,'comunicacao')}
function auditoria(){const content=header('Auditoria e Responsabilização','Rastreabilidade de acessos e acções realizadas na plataforma.',`<button class="secondary" onclick="toast('Filtro de risco aplicado')">Ver eventos de risco</button>`)+`<div class="metrics">${metric('Eventos hoje','1.284','Operações registadas')}${metric('Acessos Nível 1','47','Todos identificados')}${metric('Acessos negados','6','Sob revisão',true)}${metric('Downloads','83','Rastreáveis')}${metric('Alertas abertos','3','Responsável atribuído',true)}</div><section class="card"><div class="card-head"><h3>Registo de actividade</h3><span class="subtle">Clique para ver QUEM, O QUÊ, QUANDO e ONDE</span></div><div class="card-body"><div class="filter-row"><input placeholder="Pesquisar utilizador ou recurso…"><select><option>Todas as acções</option><option>Acesso</option><option>Alteração</option></select><select><option>Todas as áreas</option><option>Documentação</option><option>Candidaturas</option></select><select><option>Todos os níveis</option><option>Nível 1</option><option>Nível 2</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Hora</th><th>Utilizador</th><th>Acção</th><th>Recurso</th><th>Nível</th><th>Resultado</th></tr></thead><tbody>${audit.map((a,i)=>`<tr class="clickable" onclick="go('actividade/aud-${i+1}')"><td class="code">${a[0]}</td><td>${a[1]}</td><td><strong>${a[2]}</strong></td><td>${a[3]}</td><td>${level(a[4])}</td><td><span class="status ${a[5]==='Negado'?'bad':'good'}">${a[5]}</span></td></tr>`).join('')}</tbody></table></div></div></section>`;app.innerHTML=shell(content,'auditoria')}
function activity(id){const a=audit[(parseInt(id.split('-')[1])||1)-1]||audit[3];const content=header('Detalhe da actividade',`Evento ${id.toUpperCase()} · registo demonstrativo de rastreabilidade`)+`<section class="doc-hero"><span class="eyebrow" style="color:#ffcbd1">Activity Trace</span><h1>${a[2]}</h1><p>${a[3]} · ${a[0]} · ${a[5]}</p><div class="watermark">EVENTO RASTREÁVEL · PG13-AUD-${id.toUpperCase()}</div></section><div class="trace-grid" style="margin-top:16px"><div class="trace"><span>Quem?</span><strong>${a[1]} · Gestor Documental</strong></div><div class="trace"><span>O quê?</span><strong>${a[2]}</strong></div><div class="trace"><span>Quando?</span><strong>18 Set 2026 · ${a[0]}</strong></div><div class="trace"><span>Onde?</span><strong>Maputo · Rede institucional</strong></div><div class="trace"><span>Em que recurso?</span><strong>${a[3]}</strong></div><div class="trace"><span>Com que permissão?</span><strong>${a[4]} · Autorizada</strong></div></div><section class="card" style="margin-top:16px"><div class="card-head"><h3>Contexto técnico demonstrativo</h3></div><div class="card-body"><div class="detail-list"><div class="detail-item"><span>Dispositivo</span><strong>Estação institucional · CHROME-WIN</strong></div><div class="detail-item"><span>Sessão</span><strong class="code">PG13-SESS-82A4…</strong></div><div class="detail-item"><span>Resultado</span><span class="status good">${a[5]}</span></div></div><div class="warning-box">Este registo demonstra rastreabilidade de acções do sistema; não constitui prova absoluta de autoria de eventual divulgação externa.</div></div></section>`;app.innerHTML=shell(content,'auditoria')}
function aprendizagem(){const content=header('Memória e Aprendizagem Institucional','Conhecimento, liderança, história e formação ao serviço da organização.')+`<section class="learning-hero"><div class="learning-copy"><span class="eyebrow">Património institucional</span><h2>Aprender com a experiência.<br>Preparar com método.</h2><p>Um espaço organizado para preservar orientações, memória e conhecimento institucional. Os conteúdos históricos apresentados são estruturas demonstrativas a substituir por informação oficial.</p><button class="primary" onclick="go('lideranca')">Explorar liderança</button></div><div class="archive-art"><div><strong>13</strong><br><span>Congressos · Memória · Futuro</span></div></div></section><section class="module-grid" style="margin-top:16px">${[['Liderança','Perfis institucionais e responsabilidades','lideranca'],['História','Linha temporal preparada para conteúdo oficial','aprendizagem'],['Estrutura','Organização institucional e órgãos','estrutura'],['Documentos de Orientação','Biblioteca de referências controladas','documentacao'],['Congressos','Arquivo e aprendizagem entre congressos','aprendizagem'],['Formação','Percursos e materiais de capacitação','aprendizagem']].map(x=>`<a class="module" href="#/${x[2]}"><div class="module-icon">${svg('book')}</div><h3>${x[0]}</h3><p>${x[1]}</p></a>`).join('')}</section><section class="card" style="margin-top:16px"><div class="card-head"><h3>Linha de memória institucional</h3><span class="subtle">Conteúdo demonstrativo neutro</span></div><div class="card-body timeline">${[['Marco institucional','Espaço reservado para registo histórico oficial.'],['Ciclo de aprendizagem','Síntese de orientações e lições aprovadas.'],['Preparação do 13.º Congresso','Documentação progressiva do processo organizativo.']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></section>`;app.innerHTML=shell(content,'aprendizagem')}
function lideranca(){const leaders=[['Presidente','Perfil institucional principal'],['Secretário-Geral','Coordenação e orientação central'],['Dirigente Central','Perfil institucional substituível'],['Responsável de Área','Coordenação funcional demonstrativa'],['Responsável Provincial','Estrutura territorial'],['Responsável de Formação','Memória e aprendizagem']];const content=header('Liderança','Galeria preparada para fotografias, perfis e informação oficial.')+`<div class="warning-box" style="margin-bottom:16px">As fotografias e descrições abaixo são espaços substituíveis. Não representam um directório oficial.</div><section class="leader-grid">${leaders.map((x,i)=>`<article class="leader"><div class="portrait"></div><div class="leader-copy"><span class="eyebrow">${x[0]}</span><h3>${i===0?'Perfil institucional':`Dirigente demonstrativo ${i}`}</h3><p>${x[1]}. Conteúdo a validar pela instituição.</p></div></article>`).join('')}</section>`;app.innerHTML=shell(content,'aprendizagem')}
function configuracoes(){const mods=[['Utilizadores','Contas, funções e estados','utilizadores'],['Funções','Papéis operacionais e de gestão','permissoes'],['Permissões','Matriz hierárquica de acesso','permissoes'],['Classificação de Informação','Níveis 1 a 5 e políticas','permissoes'],['Estruturas','Nacional, provincial e distrital','estrutura'],['Províncias / Distritos','Estruturas territoriais','estrutura'],['Segurança','Sessões e capacidades previstas','configuracoes'],['Auditoria','Retenção e registo de eventos','auditoria'],['Preferências','Idioma, datas e apresentação','configuracoes']];const content=header('Configurações','Administração funcional e técnica da plataforma.')+`<section class="module-grid">${mods.map(x=>`<a class="module" href="#/${x[2]}"><div class="module-icon">${svg('settings')}</div><h3>${x[0]}</h3><p>${x[1]}</p></a>`).join('')}</section><section class="card" style="margin-top:16px"><div class="card-head"><h3>Separação de responsabilidades</h3></div><div class="card-body grid grid-3"><div class="warning-box"><strong>Administrador do Sistema</strong><br>Opera a plataforma e configura serviços. Não recebe automaticamente acesso a documentos classificados.</div><div class="warning-box"><strong>Gestores de Conteúdo</strong><br>Gerem informação nas áreas e estruturas especificamente autorizadas.</div><div class="warning-box"><strong>Aprovadores</strong><br>Validam decisões e documentos dentro da sua competência formal.</div></div></section>`;app.innerHTML=shell(content,'configuracoes')}
function utilizadores(){const users=[['João Demonstrativo','Gestor Provincial','Nampula','Documentação','Nível 3','Activo'],['Ana de Teste','Aprovadora','Gabinete Central','Candidaturas','Nível 1','Activo'],['Carlos Exemplo','Administrador Técnico','Nacional','Sistema','Sem acesso documental','Activo'],['Marta Demo','Gestora de Conteúdo','Sofala','Comunicação','Nível 4','Suspenso']];const content=header('Utilizadores','Contas, funções e nível máximo de informação autorizado.',`<button class="primary" onclick="toast('Formulário de utilizador demonstrativo')">Novo utilizador</button>`)+`<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Função</th><th>Estrutura</th><th>Área</th><th>Nível máximo</th><th>Estado</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="person"><div class="mini-avatar">${u[0].split(' ').map(x=>x[0]).join('').slice(0,2)}</div><strong>${u[0]}</strong></div></td><td>${u[1]}</td><td>${u[2]}</td><td>${u[3]}</td><td>${u[4].startsWith('Nível')?level(u[4]):u[4]}</td><td><span class="status ${u[5]==='Activo'?'good':'bad'}">${u[5]}</span></td></tr>`).join('')}</tbody></table></div></section>`;app.innerHTML=shell(content,'configuracoes')}
function permissoes(){const rows=[['Gabinete Central',1,1,1,1,0],['Gabinete Provincial',0,0,1,1,1],['Gestor Documental',0,1,1,1,1],['Administrador Técnico',0,0,0,0,0],['Consulta Alargada',0,0,0,0,1]];const content=header('Permissões e Classificação','Acesso hierárquico: Nível 1 é sempre o mais sensível.')+`<div class="grid grid-equal"><section class="card"><div class="card-head"><h3>Níveis de sigilo</h3></div><div class="card-body"><div class="detail-list">${[['Nível 1','Sigilo Máximo'],['Nível 2','Muito Confidencial'],['Nível 3','Confidencial'],['Nível 4','Interno Controlado'],['Nível 5','Público / Circulação Alargada']].map((x,i)=>`<div class="detail-item">${level(x[0])}<strong>${x[1]}</strong></div>`).join('')}</div></div></section><section class="card"><div class="card-head"><h3>Princípio de menor privilégio</h3></div><div class="card-body"><p class="subtle" style="line-height:1.7">Cada utilizador vê apenas a informação necessária para a sua função, estrutura e área. A administração técnica é separada da autorização de conteúdo.</p><div class="warning-box">A matriz abaixo é demonstrativa e não representa permissões de produção.</div></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><h3>Matriz hierárquica</h3></div><div class="permission-matrix"><div>Função / Grupo</div>${[1,2,3,4,5].map(n=>`<div><strong>N${n}</strong></div>`).join('')}${rows.map(r=>`<div>${r[0]}</div>${r.slice(1).map(v=>`<div><span class="check ${v?'':'deny'}">${v?'✓':'—'}</span></div>`).join('')}`).join('')}</div></section>`;app.innerHTML=shell(content,'configuracoes')}
function leaderPhoto(person,cls=''){const initials=person.name.split(' ').map(x=>x[0]).join('').slice(0,2);return `<div class="org-photo ${cls}">${person.photo?`<img src="${person.photo}" alt="Fotografia pública de ${person.name}">`:initials}</div>`}
function leadershipOrgChart(){const president=centralLeadership[0],sg=centralLeadership[1],secretaries=centralLeadership.slice(2);return `<section class="card"><div class="card-head"><div><h3>Organograma da Direcção Central</h3><span class="subtle">Composição pública confirmada · actualizada em Setembro de 2026</span></div><span class="status good">Fonte oficial</span></div><div class="org-chart"><div class="org-level"><a class="org-person-card primary" href="#/dirigente/${president.id}">${leaderPhoto(president)}<strong>${president.name}</strong><span>${president.role}</span></a></div><div class="org-level"><a class="org-person-card secondary-level" href="#/dirigente/${sg.id}">${leaderPhoto(sg)}<strong>${sg.name}</strong><span>${sg.role}<br>${sg.area}</span></a></div><div class="org-level secretaries">${secretaries.map(p=>`<a class="org-person-card secretary" href="#/dirigente/${p.id}">${leaderPhoto(p)}<strong>${p.name}</strong><span>${p.area}</span></a>`).join('')}</div><div class="org-chart-legend"><span>● Presidência</span><span>● Secretaria-Geral</span><span>● Secretariado do Comité Central</span></div></div></section>`}
function lideranca(){const content=detailHeader('aprendizagem','Aprendizagem','Liderança e Estrutura Central','Organograma da Presidência, Secretaria-Geral e Secretariado do Comité Central confirmado.')+`<div class="warning-box" style="margin-bottom:16px">Os nomes, cargos, áreas e retratos abaixo foram confirmados na publicação oficial da FRELIMO. Cada perfil mantém uma ligação directa para a fonte institucional.</div>${leadershipOrgChart()}<section class="card" style="margin-top:16px"><div class="card-head"><div><h3>Secretariado Central confirmado</h3><span class="subtle">Clique num dirigente para abrir o perfil institucional</span></div><a class="link" href="https://www.frelimo.org.mz/?p=5245" target="_blank" rel="noreferrer">Fonte oficial ↗</a></div><div class="card-body"><div class="leader-grid">${centralLeadership.map(p=>`<a class="leader" href="#/dirigente/${p.id}"><div class="portrait ${p.photo?'has-photo':''}">${p.photo?`<img src="${p.photo}" alt="Fotografia pública de ${p.name}">`:''}</div><div class="leader-copy"><span class="eyebrow">${p.level}</span><h3>${p.name}</h3><p>${p.role}<br><strong>${p.area}</strong></p><div class="role-strip"><span class="verified">✓ Informação verificada</span><span class="link">Abrir →</span></div></div></a>`).join('')}</div></div></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>Gabinete Central de Preparação do 13.º Congresso</h3><span class="subtle">Chefe do Gabinete: Chakil Aboobacar · equipas publicadas pela FRELIMO</span></div><a class="link" href="https://www.frelimo.org.mz/?p=6568" target="_blank" rel="noreferrer">Fonte oficial ↗</a></div><div class="card-body org-grid">${congressOffice.map(o=>`<article class="org-unit"><h4>${o.area}</h4><div class="org-person"><span>Chefe</span><strong>${o.head}</strong></div><div class="org-person"><span>Chefias adjuntas</span><strong>${o.deputies}</strong></div></article>`).join('')}</div></section>`;app.innerHTML=shell(content,'aprendizagem')}
function dirigentePage(id){const p=centralLeadership.find(x=>x.id===id)||centralLeadership[0];const content=detailHeader('lideranca','Liderança',p.name,`${p.role} · ${p.level}`)+`<section class="profile-hero"><div class="profile-photo">${p.photo?`<img src="${p.photo}" alt="Fotografia pública de ${p.name}">`:`<div class="portrait" style="width:100%;height:100%;border:0;border-radius:0"></div>`}</div><div class="profile-copy"><span class="eyebrow">${p.level}</span><h2>${p.name}</h2><p>${p.role}. No organograma central da PG13, este perfil está associado à área <strong>${p.area}</strong>.</p><div class="fact-list"><div class="fact"><span>Órgão</span><strong>Direcção Central da FRELIMO</strong></div><div class="fact"><span>Responsabilidade</span><strong>${p.area}</strong></div><div class="fact"><span>Estado da informação</span><strong>Confirmada em fonte pública</strong></div><div class="fact"><span>Classificação na PG13</span><strong>Nível 5 · Informação pública</strong></div></div><div class="source-note">Fonte consultada: <a href="${p.source}" target="_blank" rel="noreferrer">${p.sourceLabel} ↗</a></div></div></section><div class="grid grid-equal" style="margin-top:16px"><section class="card"><div class="card-head"><h3>Responsabilidades na plataforma</h3></div><div class="card-body"><div class="detail-list"><div class="detail-item"><span>Área principal</span><strong>${p.area}</strong></div><div class="detail-item"><span>Estrutura</span><strong>Nacional</strong></div><div class="detail-item"><span>Visibilidade do perfil</span><span class="status good">Pública</span></div><div class="detail-item"><span>Última verificação</span><strong>22 Set 2026</strong></div></div></div></section><section class="card"><div class="card-head"><h3>Actividade institucional</h3></div><div class="card-body timeline"><div class="timeline-item"><strong>Composição confirmada</strong><p>Perfil associado ao Secretariado Central publicado pela FRELIMO.</p></div><div class="timeline-item"><strong>Integração PG13</strong><p>Posição apresentada no organograma demonstrativo da plataforma.</p></div></div></section></div>`;app.innerHTML=shell(content,'aprendizagem')}
function showNotifications(){modal('Notificações',`<div class="task"><div><strong>Documento Nível 1 aguarda aprovação</strong><p>Há 12 minutos · Documentação</p></div><span class="status bad">Crítico</span></div><div class="task"><div><strong>Nampula submeteu relatório</strong><p>Há 34 minutos · Estrutura Nacional</p></div><span class="status good">Novo</span></div><div class="task"><div><strong>3 distritos ultrapassaram o prazo</strong><p>Há 1 hora · Tarefas</p></div><span class="status warn">Atenção</span></div>`)}
function openComm(){modal('Novo Comunicado',`<div class="field"><label>Título</label><input placeholder="Título do comunicado"></div><div class="field"><label>Destinatários</label><select><option>Nacional</option><option>Província</option><option>Distrito</option><option>Área</option><option>Grupo</option></select></div><button class="primary" style="width:100%" onclick="closeModal();toast('Comunicado guardado como rascunho')">Guardar rascunho demonstrativo</button>`)}
function modal(title,body){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal" onclick="if(event.target===this)closeModal()"><div class="modal-box"><div class="modal-head"><strong>${title}</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div></div></div>`)}function closeModal(){document.querySelector('#modal')?.remove()}function toast(t){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${t}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2600)}
function filterRows(q){q=q.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}
function updateDays(){const el=document.querySelector('#days');if(el)el.textContent=Math.max(0,Math.ceil((new Date('2027-07-20')-new Date())/86400000)).toLocaleString('pt-PT')}
function router(){const raw=location.hash.replace(/^#\/?/,'')||'login';const [path,query]=raw.split('?');const parts=path.split('/');const routes={login,dashboard,mapa,estrutura:structure,delegados:delegatesPage,candidaturas,documentacao,logistica,comunicacao,auditoria,aprendizagem,lideranca,configuracoes,utilizadores,permissoes};if(parts[0]==='provincia')return provincePage(parts[1]);if(parts[0]==='distrito')return districtPage(parts[1]);if(parts[0]==='delegado')return delegatePage(parts[1]);if(parts[0]==='candidatura')return candidaturaPage(parts[1]);if(parts[0]==='documento')return documento(parts[1]);if(parts[0]==='actividade')return activity(parts[1]);(routes[parts[0]]||dashboard)();window.scrollTo(0,0)}
window.addEventListener('hashchange',router);router();
function renderDeepRoute(){const path=location.hash.replace(/^#\/?/,'').split('?')[0].split('/');if(path[0]==='dirigente')dirigentePage(path[1])}
function enhanceNavigation(){const path=location.hash.replace(/^#\/?/,'').split('?')[0].split('/');const map={provincia:['estrutura','Estrutura Nacional'],distrito:['estrutura','Estrutura Nacional'],delegado:['delegados','Delegados'],candidatura:['candidaturas','Candidaturas'],documento:['documentacao','Documentação'],actividade:['auditoria','Auditoria'],utilizadores:['configuracoes','Configurações'],permissoes:['configuracoes','Configurações']};const parent=map[path[0]],title=document.querySelector('.page-title'),heading=title?.querySelector('h1')?.textContent;if(!parent||!title||title.querySelector('.back-btn'))return;title.insertAdjacentHTML('afterbegin',`<button class="back-btn" onclick="go('${parent[0]}')">← Voltar para ${parent[1]}</button><div class="breadcrumb"><a href="#/dashboard">PG13</a><span>›</span><a href="#/${parent[0]}">${parent[1]}</a><span>›</span><strong>${heading||''}</strong></div>`);title.classList.add('page-context')}
function enhanceInstitutionalImages(){if(location.hash.includes('/dashboard')){const portrait=document.querySelector('.institutional .portrait');if(portrait){portrait.classList.add('has-photo');portrait.innerHTML='<img src="assets/leadership/daniel-chapo.jpg" alt="Retrato oficial de Daniel Francisco Chapo">'}}}
function enhanceLeadershipNav(){const route=location.hash.replace(/^#\/?/,'').split('/')[0];if(route==='lideranca'||route==='dirigente'){document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#/lideranca'))}if(route==='lideranca'){document.querySelector('.back-btn')?.remove();document.querySelector('.breadcrumb')?.remove()}}
window.addEventListener('hashchange',()=>{renderDeepRoute();setTimeout(()=>{enhanceNavigation();enhanceInstitutionalImages();enhanceLeadershipNav()},0)});renderDeepRoute();setTimeout(()=>{enhanceNavigation();enhanceInstitutionalImages();enhanceLeadershipNav()},0);
